static inline const glyph_desc_t *get_date_glyph(char c) {
    if (c >= 'a' && c <= 'z') return &s_date_glyphs[c - 'a'];
    if (c >= 'A' && c <= 'Z') return &s_date_glyphs[c - 'A'];
    if (c == ',') return &s_date_glyphs[26];
    if (c >= '0' && c <= '9') return &s_date_glyphs[27 + (c - '0')];
    return NULL;
}
